import { COURSES } from './curriculum.mjs';
import { courseAccess, dependencyMet } from './progression.mjs';
import { courseRelationships, CONNECTION_TYPES } from './connections.mjs';
import {renderGradeCalculator} from './grade-calculator.mjs';
import {renderSyllabusSection} from './course-content.mjs';

export const COURSE_SECTIONS = [
 { numeral:'I', title:'Course description', note:'The official course description will appear here when the course files are added.' },
 { numeral:'II', title:'Topic rundown', note:'The topic list will appear here when the course files are added.' },
 { numeral:'III', title:'Skills for the future', note:'Important topics and skills for later courses will appear here when the course files are added.' },
 { numeral:'IV', title:'Grade calculator', note:'The grading scheme will be added from your course syllabus.' },
 { numeral:'V', title:'Mastery quiz', note:'The mastery quiz will be added after you provide the quiz files.' }
];
export const courseSections=course=>course.courseKind==='LAB'?COURSE_SECTIONS.slice(0,4):COURSE_SECTIONS;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function renderCoursePanel(progress,c,{preview=false,section=0,reward=null}={}){
 const sections=courseSections(c);section=Math.max(0,Math.min(sections.length-1,section));
 const current=sections[section],access=courseAccess(progress,c.id,{preview}),record=progress.academicRecords[c.id];
 const authored=renderSyllabusSection(c,section);
 const note=section===2?(c.courseKind==='LAB'?'Verified technical practice and software skills will appear here with examples of evidence to keep and resume wording.':'Each topic will name the future subject where it is used and recalled. CIVINCO connections will follow once its course files are reviewed.'):section===1?'A compact, grouped topic summary will appear here when the course files are added.':current.note;
 const skillsScaffold=section===2&&c.courseKind==='LAB'?'<ul class="future-skill-scaffold"><li>Technical practice<span>Specific tasks supported by your lab files</span></li><li>Software and tools<span>Only tools actually covered by the course</span></li><li>Evidence and resume wording<span>Describe what you have practiced and can demonstrate</span></li></ul>':'';
 const links=courseRelationships(COURSES,c.id);
 const met=(id,type)=>dependencyMet(progress,id,type,{lab:c.courseKind==='LAB'&&type==='C'});
 const relationshipRows=(rows,{incoming=false}={})=>rows.map(({course:other,type})=>`<div class="dossier-prereq dossier-relation ${incoming&&met(other.id,type)?'is-met':''}" data-related-course="${other.id}" data-relation-type="${type}"><span class="relation-type" title="${CONNECTION_TYPES[type]}">${type}</span><button data-course-link="${other.id}"><strong>${other.id}</strong><span>${esc(other.title)}</span>${other.specialization?'<small>'+other.specialization+' specialization</small>':''}</button><span class="relation-arrow" aria-hidden="true">${incoming&&met(other.id,type)?'✓':'↗'}</span></div>`).join('');
 const relationships=`<details class="dossier-relationships"><summary><span>Course requirements & connections</span><small>${links.prerequisites.length} prerequisites · ${links.leadsTo.length} next courses · ${links.corequisites.length} co-requisites</small></summary><section class="dossier-connections" aria-label="Course prerequisites"><h4>Prerequisites</h4>${links.prerequisites.length?relationshipRows(links.prerequisites,{incoming:true}):'<p>No course prerequisites.</p>'}</section><section class="dossier-connections" aria-label="Courses that require this course"><h4>Prerequisite for</h4>${links.leadsTo.length?relationshipRows(links.leadsTo):'<p>No downstream prerequisite courses in this curriculum.</p>'}</section><section class="dossier-connections" aria-label="Co-requisite courses"><h4>Co-requisite with</h4>${links.corequisites.length?relationshipRows(links.corequisites,{incoming:c.courseKind==='LAB'}):'<p>No co-requisite courses.</p>'}</section><dl class="dossier-key"><div><dt>H</dt><dd>Hard prerequisite · academically completed</dd></div><div><dt>S</dt><dd>Soft prerequisite · activated or completed</dd></div><div><dt>C</dt><dd>${c.courseKind==='LAB'?'Lecture must be taken in this term or an earlier term; lab cannot come first.':'Lecture co-requisites activate together; labs activate separately after their lecture.'}</dd></div></dl><p class="dossier-mastery-scope">${c.requiredMastery?'Required Normal Mode mastery node.':'Academic requirement · Mastery not required.'}</p></details>`;
 const status=preview?'Preview only':record?.status==='COMPLETED'?'Academically completed':record?.status==='ACTIVE'?'Course active':access.allowed?'Ready to activate':'Not yet available';

 const celebration=!preview&&reward?.id===c.id;
 const rewardMarkup=celebration?`<div class="completion-reward" role="status"><span class="reward-star" aria-hidden="true">✦</span><div><h4>${reward.termComplete?'Term '+reward.term+' constellation complete':'A new star in your sky'}</h4><p>${reward.academic.complete} / ${reward.academic.total} academic courses complete${reward.newlyAvailable.length?' · '+reward.newlyAvailable.length+' now ready to activate':''}</p></div></div><button class="secondary reward-return" data-action="close-inspector">Return to the sky ↗</button>`:'';
 const action=celebration?rewardMarkup:preview?`<p class="dossier-readonly">Preview only · Academic records stay unchanged.</p>`:record?.status==='COMPLETED'?'<p class="dossier-readonly">Academic completion recorded by you. Mastery is assessed separately.</p>':`<button class="primary dossier-academic" data-academic="${record?.status==='ACTIVE'?'COMPLETED':'ACTIVE'}" ${access.allowed?'':'disabled'}>${record?.status==='ACTIVE'?'Record academic completion':access.coactivate?.length?'Activate '+[c.id,...access.coactivate].join(' + '):'Activate course'}</button><p class="dossier-reason">${esc(access.reason)}</p>`;
 return `<div class="dossier-layout ${celebration?'is-celebrating':''}"><button class="dossier-close" data-action="close-inspector" aria-label="Close course details" autofocus>×</button><div class="dossier-identity"><span class="dossier-path">${c.specialization||'SHARED CIVIL ENGINEERING'}</span><div class="dossier-heading"><span class="course-code">${c.id}</span><h2 id="dossier-title">${esc(c.title)}</h2><div class="course-meta"><span>Year ${c.year}</span><span>Term ${c.term}</span><span>${c.units} unit${c.units!==1?'s':''}</span></div><span class="course-status ${preview?'preview-status':''}">${status}</span></div></div><div class="dossier-tabs" style="--course-tab-count:${sections.length}" role="tablist" aria-label="Course sections"><span class="dossier-thread" aria-hidden="true"></span>${sections.map((s,i)=>`<button id="course-tab-${i}" class="dossier-tab" role="tab" aria-selected="${i===section}" aria-controls="course-section" tabindex="${i===section?0:-1}" data-course-section="${i}" aria-label="${s.numeral}: ${s.title}" title="${s.title}"><span class="dossier-diamond" aria-hidden="true"></span><span class="dossier-numeral">${s.numeral}</span><span class="dossier-tab-name">${['Overview','Topics','Skills','Grades','Quiz'][i]}</span></button>`).join('')}</div><div class="dossier-reading"><header class="dossier-section-heading"><span aria-hidden="true">${current.numeral}</span><h3>${current.title}</h3></header><div class="dossier-scroll"><section id="course-section" role="tabpanel" aria-labelledby="course-tab-${section}" tabindex="0">${section===3?renderGradeCalculator(c):authored||`<div class="dossier-placeholder"><span class="dossier-small-star" aria-hidden="true">✦</span><h4>${section===4?'Quiz coming later':'Awaiting course files'}</h4><p>${note}</p>${skillsScaffold}${section===4?'<button class="secondary" disabled>Mastery quiz · Coming later</button>':''}</div>`}</section>${relationships}</div><footer class="dossier-footer">${action}</footer></div></div>`;
}
